  const colorEditor=document.createElement('div');colorEditor.className='visual-color-editor';colorEditor.hidden=true;colorEditor.innerHTML='<button type="button" data-color-back>Palette</button><div class="visual-color-matrix" role="group" aria-label="Matrice de couleurs"></div><label>HEX<input data-color-hex maxlength="7" placeholder="#52634D" autocomplete="off" spellcheck="false" aria-label="Code hexadécimal"></label><label>RGB<input data-color-rgb placeholder="82, 99, 77" autocomplete="off" spellcheck="false" aria-label="Code RGB"></label>';studio.querySelector('[data-panel=color]').append(colorEditor);
