  rgbInput.oninput=()=>{const values=rgbInput.value.trim().replace(/^rgb\(\s*|\s*\)$/gi,'').split(/[,\s]+/);if(values.length===3&&values.every(x=>/^\d{1,3}$/.test(x)&&Number(x)<=255))applyColor('#'+values.map(x=>Number(x).toString(16).padStart(2,'0')).join(''))};
  function hueHex(h,l){const a=.7*Math.min(l,1-l),f=n=>{const k=(n+h/30)%12;return Math.round(255*(l-a*Math.max(-1,Math.min(k-3,9-k,1))))};return '#'+[f(0),f(8),f(4)].map(x=>x.toString(16).padStart(2,'0')).join('')}
